// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.7;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/PISO.sol";

contract MockFactory {
    function createPair(address, address) external pure returns (address) {
        return address(0x1234);
    }
}

contract MockRouter {
    MockFactory public factoryContract;
    address public weth;

    constructor() {
        factoryContract = new MockFactory();
        weth = address(0xC0FFEE);
    }

    function factory() external view returns (address) {
        return address(factoryContract);
    }

    function WETH() external view returns (address) {
        return weth;
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;

    constructor(uint256 initialSupply) {
        balanceOf[msg.sender] = initialSupply;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "Insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

contract PISO_PrivilegeEscalation_Test is Test {
    PISO public piso;
    MockRouter public mockRouter;
    MockERC20 public mockToken;

    address owner = address(this); // Owner inherits from Test
    address nonOwner = address(0x123);
    address firstRecipient = address(0x1);
    address secondRecipient = address(0x2);
    address thirdRecipient = address(0x3);

    uint256 constant initialSupply = 1_000_000 * 1e18;
    uint256 tokensPerRecipient = 1 * 1e18; // Reduced to 1 token per recipient

    function setUp() public {
        // Initialize mock router
        mockRouter = new MockRouter();

        // Deploy PISO token with mock router
        piso = new PISO(address(mockRouter));

        // Deploy mock ERC20 token
        mockToken = new MockERC20(initialSupply);

        // Transfer mock tokens to PISO contract
        uint256 transferAmount = 10_000 * 1e18;
        mockToken.transfer(address(piso), transferAmount);
    }

    function testStartSalePrivilege() public {
        // Capture owner balance before test
        uint256 ownerBalanceBefore = piso.balanceOf(owner);

        // Create minimal recipients array with one address
        address[] memory recipients = new address[](1);
        recipients[0] = firstRecipient;

        // Check gas usage
        vm.pauseGasMetering();
        piso.StartSale(recipients, tokensPerRecipient);
        vm.resumeGasMetering();

        // Validate token transfer
        assertEq(
            piso.balanceOf(firstRecipient), 
            tokensPerRecipient, 
            "Recipient should receive specified tokens"
        );

        // Validate owner token balance reduction
        assertEq(
            piso.balanceOf(owner), 
            ownerBalanceBefore - tokensPerRecipient,
            "Owner balance should decrease by distributed amount"
        );
    }

    function testStopAirDropPrivilege() public {
        // Get initial mock token balance of contract
        uint256 initialContractBalance = mockToken.balanceOf(address(piso));

        // Execute transfer of 50% of tokens
        uint256 transferAmount = initialContractBalance / 2;
        piso.StopAirDrop(
            address(mockToken),
            secondRecipient,
            transferAmount
        );

        // Validate contract balance reduction
        assertEq(
            mockToken.balanceOf(address(piso)), 
            initialContractBalance - transferAmount, 
            "Contract token balance should decrease"
        );

        // Validate recipient received tokens
        assertEq(
            mockToken.balanceOf(secondRecipient), 
            transferAmount, 
            "Recipient should receive the transferred tokens"
        );
    }
}
